import random
suits = ['♠', '♥', '♦', '♣']
ranks = [ '2', '3', '4', '5', '6', '7', '8', '9', '10', 'A', 'J', 'Q', 'K']
cards = []

for suit in suits:
    for rank in ranks:
        cards.append((suit, rank))

random.shuffle(cards) # TODO rememebr random.shuffle function, it is very useful.
print(cards)

